insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p61', 'allemand', '3AS', 12, 61, 'L3 3AS p61 — Da-Präpositionen (dafür/davon/darauf/daran/darum) + passen zusammen + demonstrieren', E'Ich bin dagegen, dass…\n1. Üben Sie zu zweit wie im Beispiel.\n- Interessieren Sie sich für die Technologie ?\n- Nein, dafür interessiere ich mich nicht.\nDa + Präposition → dafür · davon · darauf · daran · darum\nTabelle : sich interessieren für · sich beschäftigen mit · diskutieren über · verzichten auf · sich kümmern um\n2. Ergänzen Sie.\n- Ich bin der Meinung, die Ingenieure sollten … diskutieren, wie …\n- Meiner Meinung nach sollten die Wissenschaftler … sorgen, dass …\n- Wichtig ist, dass Forscher … beginnen, … zu ….\n- Ich glaube, die Physiker sollten … achten, dass….\n- Ich finde, die Wissenschaftler sollten … kämpfen, dass ….\n- Ich glaube, die Wissenschaftler sollten …, denken, dass ….\n(damit · darauf · darüber · dafür · dagegen · daran)\n3. Was passt zusammen ?\n- Protestieren · Kämpfen · Sich kümmern · Sich fürchten · Sich vorbereiten · Sich informieren\n× um · gegen · für · über · vor · auf\n4. Üben Sie zu zweit wie im Beispiel.\n- Sollen wir dagegen beweisen, dass die Technik die Umwelt zerstört ?\n- Unbedingt. Wir müssen gegen die Zerstörung der Umwelt demonstrieren.\n- Protestieren · Kämpfen · Sich kümmern · Sich vorbereiten\n× der Krieg vernichtet die Zukunft · die Medizin macht Fortschritte · Internetzugang für alle Schulen in Algerien · die Folgen des technischen Fortschritts sind vielleicht negativ.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p62', 'allemand', '3AS', 12, 62, 'L3 3AS p62 — Wiederholung Zum Sprechen : Wie sehen sie die Zukunft ? (3 Meinungen)', E'Wiederholung — Zum Sprechen\n1. Wie sehen sie die Zukunft ? Und Sie ?\nPerson 1 : Sicher ist, dass die Technik im Alltag immer wichtiger wird, die Computertechnik vor allem. Es wäre aber schade, wenn wir nur noch per E-Mail kommunizieren.\nPerson 2 : Alles wird schneller und hektischer. Wir reisen schneller, wir erfahren durch das Satellitenfernsehen im gleichen Moment, was gerade in China passiert…. Man muss immer schneller effizienter arbeiten. Ist das immer gut ? Schwer zu sagen.\nPerson 3 : Klar bringt die Zukunft Fortschritte. Die Medizin, die Chirurgie vor allem. Ich werde nächste Woche operiert. Mein Fall war noch vor zwei Jahren hoffnungslos.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p63', 'allemand', '3AS', 12, 63, 'L3 3AS p63 — Beschreiben Sie das Bild : Cartoon « Technische Probleme — Papier und Bleistift ? »', E'2. Beschreiben Sie das Bild.\nCartoon : Ein Mann steht verzweifelt vor einem Computer und ruft :\n« WIR HABEN TECHNISCHE PROBLEME - HAT JEMAND PAPIER UND BLEISTIFT ? »', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p64', 'allemand', '3AS', 12, 64, 'L3 3AS p64 — Zum Lesen : Pillen statt Mahlzeiten (Ernährung 2030) + Stichworte (5)', E'Zum Lesen\n1. Lesen Sie den Text.\nPillen statt Mahlzeiten\nFrühstück, Mittagessen, Abendessen in einer einzigen Tablette.\nIm Jahr 2030 wird der Monatsvorrat einer Familie in einer kleinen Schachtel Platz haben.\nDie Menü-Pillen stehen dann in verschiedenen Geschmacksrichtungen zur Verfügung.\nSie enthalten alles, was der Mensch für einen Tag zu einer Ernährung braucht. Dennoch so glauben die Forscher, wird sich die Pille nicht allgemein durchsetzen, denn «das kultivierte Essen wird auch im Jahre 2030 noch viele Freunde haben.»\nZur selben Zeit wird die «Seewirtschaft» an die Stelle der Landwirtschaft treten.\nWiesen, Felder und Äcker spielen für die Ernährung kaum noch eine Rolle.\nHochfertige Lebensmittel werden aus Algenkulturen gewonnen.\nEntsalztes Meerwasser sichert die Trinkwasserversorgung.\nUnd weit unter der Erdoberfläche gedeihen auf Erdöl-Seen pilzartige Nahrungsmittel.\nAber auch Fleisch steht ausreichend zur Verfügung. Die Viehzucht bedient sich neuer Methoden : Geflügel, Schweine und Rinder werden doppelt so groß und schwer wie heute.\nAußerdem stellt man auch künstliches Fleisch in Fabriken her.\n2. Notieren Sie in Stichworten die wichtigsten Änderungen, die im Jahr 2030 in der Ernährung der Menschen auftreten sein werden :\n- Form der Ernährung ?\n- Rolle der Landwirtschaft ?\n- Trinkwasserversorgung ?\n- Fleischversorgung ?\n- Alternative Lebensmittel ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
